'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var powf = require( '@stdlib/math/base/special/powf' );
var floorf = require( '@stdlib/math/base/special/floorf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var log10 = require( '@stdlib/math/base/special/log10' );


// VARIABLES //

var ZERO = f32( 0.0 );
var ONE = f32( 1.0 );
var TEN = f32( 10.0 );


// MAIN //

/**
* Rounds a single-precision floating point number to the nearest power of `10` toward zero.
*
* @param {number} x - input value
* @returns {number} rounded value
*
* @example
* var v = trunc10f( 3.141592653589793 );
* // returns 1.0
*
* @example
* var v = trunc10f( 13.0 );
* // returns 10.0
*/
function trunc10f( x ) {
	var sign;
	x = f32( x );
	if (
		isnanf( x ) ||
		isInfinitef( x ) ||
		x === ZERO
	) {
		return x;
	}
	if ( x < ZERO ) {
		x = -x;
		sign = -ONE;
	} else {
		sign = ONE;
	}
	return sign * powf( TEN, floorf( f32( log10( x ) ) ) );
}


// EXPORTS //

module.exports = trunc10f;
